SELECT u.id, u.username, u.display_name FROM users u  LEFT JOIN astra_user_search s ON s.user_id=u.id  WHERE u.status='active' AND u.id<>$1  AND ($2='' OR (u.username,u.id)>($2,$3))  AND (s.user_id IS NULL OR s.source_username<>u.username OR s.source_display_name<>u.display_name  OR s.normalized_username LIKE $4 ESCAPE '!'  OR s.normalized_display_name LIKE $4 ESCAPE '!')  AND NOT EXISTS(SELECT 1 FROM block_relations b WHERE b.blocker_id=$1 AND b.blocked_id=u.id)  AND NOT EXISTS(SELECT 1 FROM block_relations b WHERE b.blocked_id=$1 AND b.blocker_id=u.id)  ORDER BY u.username,u.id
